t.script:
                document.addEventListener('DOMContentLoaded', function () {
                    if (window.__neatclover_vt_select_initialized) {
                        return;
                    }
                    window.__neatclover_vt_select_initialized = true;

                    const root = document.getElementById('neatclovervt_invoice_select_root');
                    const selectEl = document.getElementById('vtProviderSelect');
                    const originEl = document.getElementById('vtOriginSelect');
                    const msgEl = document.getElementById('vtSelectMsg');
                    const nextBtn = document.getElementById('vtSelectNext');
                    const formWrap = document.getElementById('vtSelectFormWrap');
                    const waitingWrap = document.getElementById('vtWaitingWrap');
                    const resultWrap = document.getElementById('vtResultWrap');
                    const statusEl = document.getElementById('vtCheckoutStatus');
                    const reopenBtn = document.getElementById('vtReopenPayment');
                    const backBtn = document.getElementById('vtBackToForm');
                    const resultTitle = document.getElementById('vtResultTitle');
                    const resultMessage = document.getElementById('vtResultMessage');

                    if (!root || !selectEl || !originEl || !msgEl || !nextBtn || !formWrap || !waitingWrap || !resultWrap) {
                        return;
                    }

                    const wizardId = root.dataset.wizardId || '';
                    let paymentWindow = null;
                    let statusPollTimer = null;
                    let finished = false;
                    let paymentUrl = '';
                    let transactionReference = '';

                    function showMsg(text) {
                        msgEl.textContent = text || '';
                        msgEl.classList.toggle('show', !!text);
                    }

                    function setTakePaymentBusy(isBusy) {
                        nextBtn.disabled = isBusy;
                        nextBtn.dataset.processing = isBusy ? '1' : '0';
                        nextBtn.textContent = isBusy ? 'Opening...' : 'Take Payment';
                        selectEl.disabled = isBusy;
                        originEl.disabled = isBusy;
                    }

                    function setWizardIframeHeight(minHeight, height) {
                        try {
                            var f = window.frameElement;
                            if (!f) {
                                return;
                            }
                            f.style.minHeight = minHeight;
                            f.style.height = height;
                            f.style.maxHeight = '';
                            f.style.overflow = 'auto';
                        } catch (e) {}
                    }

                    function setWizardDialogWidth(widthPx) {
                        try {
                            if (!window.parent || window.parent === window) {
                                return;
                            }
                            var parentDoc = window.parent.document;
                            var dialog = parentDoc.querySelector('.modal.show .modal-dialog')
                                || parentDoc.querySelector('.o_dialog .modal-dialog')
                                || parentDoc.querySelector('.modal-dialog');
                            if (dialog) {
                                dialog.style.maxWidth = widthPx;
                                dialog.style.width = widthPx;
                            }
                        } catch (e) {}
                    }

                    function showForm() {
                        finished = false;
                        formWrap.style.display = 'block';
                        waitingWrap.style.display = 'none';
                        resultWrap.style.display = 'none';
                        setWizardIframeHeight('380px', '420px');
                        setWizardDialogWidth('462px');
                    }

                    function showWaiting() {
                        formWrap.style.display = 'none';
                        waitingWrap.style.display = 'block';
                        resultWrap.style.display = 'none';
                        statusEl.textContent = 'Waiting for payment...';
                        setWizardIframeHeight('320px', '360px');
                        setWizardDialogWidth('462px');
                    }

                    function closePaymentWindow() {
                        try {
                            if (paymentWindow && !paymentWindow.closed) {
                                paymentWindow.close();
                            }
                        } catch (e) {}
                        paymentWindow = null;
                    }

                    function stopPolling() {
                        if (statusPollTimer) {
                            clearInterval(statusPollTimer);
                            statusPollTimer = null;
                        }
                    }

                    function showResult(success, message) {
                        finished = true;
                        stopPolling();
                        closePaymentWindow();
                        formWrap.style.display = 'none';
                        waitingWrap.style.display = 'none';
                        resultWrap.style.display = 'block';
                        resultTitle.textContent = success ? 'Payment successful' : 'Payment declined';
                        resultTitle.className = 'result-title ' + (success ? 'ok' : 'err');
                        resultMessage.textContent = message || (
                            success
                                ? 'The payment was processed successfully.'
                                : 'The payment was declined. Please try again.'
                        );
                        setWizardIframeHeight('240px', '280px');
                        setWizardDialogWidth('462px');
                    }

                    function openPaymentPopup() {
                        if (!paymentUrl) {
                            return false;
                        }
                        var features = 'popup=yes,width=980,height=820,scrollbars=yes,resizable=yes';
                        paymentWindow = window.open(paymentUrl, 'neatclover_vt_checkout', features);
                        if (!paymentWindow) {
                            showMsg('Popup blocked. Please allow popups for this site and try again.');
                            return false;
                        }
                        try { paymentWindow.focus(); } catch (e) {}
                        return true;
                    }

                    function startStatusPolling() {
                        stopPolling();
                        statusPollTimer = setInterval(function () {
                            if (finished || !transactionReference) {
                                return;
                            }
                            try {
                                if (paymentWindow && paymentWindow.closed) {
                                    statusEl.textContent =
                                        'Payment window closed. Waiting for confirmation, or click Open Payment Popup Again.';
                                }
                            } catch (e) {}
                            fetch('/neatclovervt/payment-status?reference=' + encodeURIComponent(transactionReference), {
                                credentials: 'same-origin',
                            }).then(function (response) {
                                return response.json();
                            }).then(function (body) {
                                if (!body || !body.ok || finished) {
                                    return;
                                }
                                if (body.status === 'paid') {
                                    showResult(true, 'Payment successful! You may now close this window.');
                                } else if (body.status === 'error' || body.status === 'cancel') {
                                    showResult(false, 'The payment was declined. Please try again.');
                                }
                            }).catch(function () {});
                        }, 3000);
                    }

                    window.addEventListener('message', function (e) {
                        if (finished || !e.data || e.data.type !== 'neatclover_vt_result') {
                            return;
                        }
                        if (e.data.success) {
                            showResult(true, 'Payment successful! You may now close this window.');
                        } else {
                            showResult(false, 'The payment was declined. Please try again.');
                        }
                    });

                    nextBtn.addEventListener('click', function (e) {
                        e.preventDefault();
                        if (nextBtn.dataset.processing === '1') {
                            return;
                        }
                        const providerId = selectEl.value;
                        const origin = (originEl.value || '').toUpperCase();
                        if (!providerId) {
                            showMsg('Please select a payment provider.');
                            return;
                        }
                        if (origin !== 'MAIL' && origin !== 'PHONE') {
                            showMsg('Please select an origin (Phone or Mail).');
                            return;
                        }
                        showMsg('');
                        setTakePaymentBusy(true);
                        fetch(`/neatclovervt/invoice_payment/${wizardId}/checkout`, {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({
                                provider_id: parseInt(providerId, 10),
                                transaction_origin: origin,
                            }),
                            credentials: 'same-origin',
                        }).then(function (r) { return r.json().then(function (j) { return { ok: r.ok, body: j }; }); })
                        .then(function (res) {
                            if (!res.ok || !res.body || !res.body.ok) {
                                const err = res.body && res.body.error;
                                showMsg(err === 'checkout_failed'
                                    ? 'Could not start Clover checkout. Check the activation code and provider settings.'
                                    : err === 'invalid_origin'
                                    ? 'Please select a valid origin (Phone or Mail).'
                                    : 'Could not start checkout. Please try again.');
                                setTakePaymentBusy(false);
                                return;
                            }
                            paymentUrl = res.body.payment_url || '';
                            transactionReference = res.body.transaction_reference || '';
                            if (!paymentUrl) {
                                showMsg('Could not start checkout. Please try again.');
                                setTakePaymentBusy(false);
                                return;
                            }
                            setTakePaymentBusy(false);
                            showWaiting();
                            if (!openPaymentPopup()) {
                                showForm();
                                return;
                            }
                            statusEl.textContent = 'Payment popup opened. Waiting for payment confirmation...';
                            startStatusPolling();
                        }).catch(function () {
                            showMsg('Network error. Please try again.');
                            setTakePaymentBusy(false);
                        });
                    });

                    reopenBtn.addEventListener('click', function (e) {
                        e.preventDefault();
                        if (finished) {
                            return;
                        }
                        openPaymentPopup();
                        statusEl.textContent = 'Payment popup opened. Waiting for payment confirmation...';
                    });

                    function resetToForm() {
                        stopPolling();
                        closePaymentWindow();
                        paymentUrl = '';
                        transactionReference = '';
                        showForm();
                    }

                    backBtn.addEventListener('click', function (e) {
                        e.preventDefault();
                        resetToForm();
                    });

                    // Modal X / Close should close the payment popup the same way as Back.
                    function cleanupOnModalDismiss() {
                        stopPolling();
                        closePaymentWindow();
                        paymentUrl = '';
                        transactionReference = '';
                    }

                    try {
                        if (window.parent && window.parent !== window) {
                            var parentDoc = window.parent.document;
                            var dialog = parentDoc.querySelector('.modal.show')
                                || parentDoc.querySelector('.o_dialog .modal')
                                || parentDoc.querySelector('.o_dialog')
                                || parentDoc.querySelector('.modal');
                            if (dialog) {
                                dialog.addEventListener('hide.bs.modal', cleanupOnModalDismiss);
                                dialog.querySelectorAll(
                                    '.btn-close, [data-bs-dismiss="modal"], footer button, .modal-footer button'
                                ).forEach(function (btn) {
                                    btn.addEventListener('click', cleanupOnModalDismiss);
                                });
                            }
                        }
                    } catch (e) {}

                    window.addEventListener('pagehide', cleanupOnModalDismiss);
                    window.addEventListener('beforeunload', cleanupOnModalDismiss);

                    setWizardDialogWidth('462px');
                    setWizardIframeHeight('380px', '420px');
                });

document.addEventListener('DOMContentLoaded', function () {
    const root = document.getElementById('neatclovervt_invoice_payment_root');
    const wizardId = root ? (root.dataset.wizardId || '') : '';
    // Selection + waiting UI lives on the main VT page.
    if (wizardId) {
        window.location.replace(`/neatclovervt/invoice_payment/${wizardId}`);
    }
});

(function () {
    var status = "";
    var success = ;
    var payload = {
        type: 'neatclover_vt_result',
        status: status,
        success: success === true || success === 'true'
    };
    try {
        if (window.opener && !window.opener.closed) {
            window.opener.postMessage(payload, '*');
        }
    } catch (e) {}
    try { window.close(); } catch (e) {}
    setTimeout(function () {
        try { window.close(); } catch (e) {}
    }, 200);
})();
